"""Demo copy for the travel templates: nine kinds of travel business. All businesses, people and partners are invented."""


def attributes(trip_types, regions=('India', 'International'), group_label='Group size'):
    return [
        {'key': 'duration', 'label': 'Duration', 'type': 'number', 'suffix': 'Days', 'filter': True, 'card': True, 'icon': 'bi-calendar3'},
        {'key': 'nights', 'label': 'Nights', 'type': 'number', 'suffix': 'Nights', 'icon': 'bi-moon-stars'},
        {'key': 'trip_type', 'label': 'Trip type', 'type': 'select', 'options': list(trip_types), 'filter': True, 'card': True, 'icon': 'bi-compass'},
        {'key': 'region', 'label': 'Region', 'type': 'select', 'options': list(regions), 'filter': True, 'icon': 'bi-globe2'},
        {'key': 'group_size', 'label': group_label, 'type': 'text', 'card': True, 'icon': 'bi-people', 'help': 'e.g. Max 12 or Private'},
        {'key': 'best_time', 'label': 'Best time to go', 'type': 'text', 'icon': 'bi-sun', 'help': 'e.g. Oct – Mar'},
        {'key': 'start_city', 'label': 'Starts from', 'type': 'text', 'icon': 'bi-geo-alt'},
        {'key': 'flights', 'label': 'Flights included', 'type': 'toggle', 'filter': True, 'icon': 'bi-airplane'},
        {'key': 'highlights', 'label': 'Highlights', 'type': 'list', 'icon': 'bi-stars'},
        {'key': 'inclusions', 'label': 'What’s included', 'type': 'list', 'icon': 'bi-check-circle'},
        {'key': 'exclusions', 'label': 'Not included', 'type': 'list', 'icon': 'bi-x-circle'},
    ]


def P(title, slug, cat, scene, route, price, days, trip, region, group, best, start, flights, short, itinerary, highlights, featured=True, badge='', note='per person', closed=False):
    return {'title': title, 'slug': slug, 'cat': cat, 'scene': scene, 'route': route, 'price': price, 'days': days, 'trip': trip, 'region': region, 'group': group,
            'best': best, 'start': start, 'flights': flights, 'short': short, 'itinerary': itinerary, 'highlights': highlights, 'featured': featured, 'badge': badge,
            'note': note, 'closed': closed}


def T(name, role, bio):
    return {'name': name, 'role': role, 'bio': bio}


def S(icon, title, desc):
    return {'icon': icon, 'title': title, 'description': desc}


ENQ = lambda heading, success, select=('Travellers', ['1 traveller', '2 travellers', '3–4 travellers', '5–8 travellers', '9 or more']), date='Travel date': {
    'heading': heading, 'button': 'Send enquiry', 'date_label': date, 'select_label': select[0], 'select_options': select[1],
    'message_label': 'Anything else? (hotel preference, special requests)', 'success': success}

